+            <rect x="0" y="690" width="1200" height="210" fill="#08111a" />
+            <text x="80" y="810" fill="#f4f7fb" font-family="Inter,Segoe UI,Arial,sans-serif" font-size="74" font-weight="700">Harbor Lights</text>
