+        `;
+      }
+
+      function HeroSection() {
+        return `
+          <section class="hero" aria-labelledby="page-title">
+            <p class="eyebrow">Image Preview</p>
+            <h1 id="page-title">Review before you publish</h1>
+            <p>
+              Check the composition, metadata, and permissions for this image before it goes live or is removed from your library.
+            </p>
+            <p id="library-status" class="status-message" aria-live="polite"></p>
+          </section>
+        `;
+      }
+
+      function ImagePreviewCard() {
+        return `
+          <section class="preview-card" aria-labelledby="image-title">
+            <figure class="preview-visual" id="preview-frame">
+              <img src="${previewImage}" alt="Preview of Harbor Lights, a twilight harbor scene with mountain silhouettes and reflected lights on the water." />
+            </figure>
+            <div class="preview-content" id="preview-content">
+              <div class="preview-meta" aria-label="Image metadata">
+                <span>5472 × 3648</span>
+                <span>RAW + JPEG</span>
+                <span>Licensed</span>
+              </div>
+              <h2 id="image-title">Harbor Lights</h2>
+              <p>
