+              <p id="delete-dialog-description">
+                This permanently removes <strong>Harbor Lights</strong> from your saved library. You can cancel if you still need the file.
+              </p>
+              <div class="dialog-actions">
+                <form method="dialog">
+                  <button type="submit" class="button" value="cancel" autofocus>Cancel</button>
+                </form>
+                <button type="button" class="button button-danger" id="confirm-delete">
+                  Delete image
+                </button>
+              </div>
+            </div>
+          </dialog>
+        `;
+      }
+
+      function App() {
+        return `
+          <a class="skip-link" href="#main-content">Skip to main content</a>
+          <div class="page-shell">
+            ${Header()}
+            <main id="main-content" tabindex="-1">
+              ${HeroSection()}
+              ${ImagePreviewCard()}
+            </main>
+          </div>
+          ${DeleteDialog()}
+        `;
+      }
+
+      document.getElementById("app").innerHTML = App();
+
+      const dialog = document.getElementById("delete-dialog");
+      const trigger = document.getElementById("open-delete-dialog");
+      const confirmDelete = document.getElementById("confirm-delete");
+      const previewFrame = document.getElementById("preview-frame");
+      const previewContent = document.getElementById("preview-content");
+      const statusMessage = document.getElementById("library-status");
+
+      trigger.addEventListener("click", () => {
+        dialog.showModal();
+      });
+
+      confirmDelete.addEventListener("click", () => {
+        dialog.close("delete");
+      });
+
+      dialog.addEventListener("close", () => {
+        if (dialog.returnValue !== "delete") {
+          return;
+        }
+
+        previewFrame.outerHTML = `
+          <div class="deleted-state" tabindex="-1" id="deleted-state">
+            <div>
+              <div class="deleted-state-icon" aria-hidden="true">✓</div>
+              <h2>Image deleted</h2>
+              <p>Harbor Lights has been removed from your library and is no longer available in this collection.</p>
+            </div>
+          </div>
+        `;
+
+        previewContent.innerHTML = `
+          <div class="preview-meta" aria-label="Deletion details">
+            <span>Removed from library</span>
+            <span>Action completed</span>
+          </div>
+          <h2 id="image-title">Library updated</h2>
+          <p>
+            The selected image has been deleted. Download is no longer available for this asset.
+          </p>
+        `;
+
+        statusMessage.textContent = "Image deleted from your library.";
+        document.getElementById("deleted-state").focus();
+      });
+    </script>
+  </body>
+</html>
*** End Patch
